diff --git a/internal/smb/command/context.go b/internal/smb/command/context.go
index b1371f5..a2e7b6d 100644
--- a/internal/smb/command/context.go
+++ b/internal/smb/command/context.go
@@ -79,8 +79,14 @@ type Context struct {
 
 	// Log 是日志句柄。
 	Log *slog.Logger
+
+	// suppress 表示本条消息**不产生任何响应字节**（SMB2 CANCEL）。
+	suppress bool
 }
 
+// Suppressed 报告本条消息是否不产生响应。internal/server 据此回滚响应缓冲。
+func (c *Context) Suppressed() bool { return c.suppress }
+
 // NewContext 构造一条请求的处理上下文。
 //
 // out 必须是响应缓冲区当前内容；本函数会把响应头占位追加进去。
@@ -116,6 +122,14 @@ func (c *Context) ResetBody() {
 	c.Out = c.Out[:c.msgStart+wire.HeaderSize]
 }
 
+// discard 连响应头一起丢弃，使本条消息在缓冲里不留任何痕迹。
+func (c *Context) discard() {
+	c.Out = c.Out[:c.msgStart]
+	c.SignKey = nil
+	c.HashResponseConn = false
+	c.HashResponseSession = nil
+}
+
 // finishHeader 把 Status / Credits 写入 RespHeader 并原地回填到 Out。
 //
 // 这里利用了 Header.Append 的实现细节：对 c.Out[:msgStart] 追加 64 字节时，
diff --git a/internal/smb/command/dispatch.go b/internal/smb/command/dispatch.go
index 7365fb3..6c237d2 100644
--- a/internal/smb/command/dispatch.go
+++ b/internal/smb/command/dispatch.go
@@ -27,6 +27,12 @@ type handlerSpec struct {
 	needSession bool
 	// needTree 表示必须有一个有效的树连接。
 	needTree bool
+	// noResponse 表示本命令**永不产生响应**。
+	//
+	// 目前只有 SMB2 CANCEL（MS-SMB2 §3.3.5.16）。这类命令跳过全部前置
+	// 检查直接执行 handler，且不参与 credit 记账 —— 客户端收不到响应就
+	// 拿不回 credit，在这里扣减会让双方水位永久错位。
+	noResponse bool
 }
 
 // handlers 是命令分发表（AGENTS.md §5 P2 策略模式）。
@@ -44,12 +50,27 @@ func register(cmd wire.Command, needSession, needTree bool, fn Handler) {
 	handlers[cmd] = handlerSpec{fn: fn, needSession: needSession, needTree: needTree}
 }
 
+// registerNoResponse 登记一个**不产生响应**的命令处理器（见 handlerSpec.noResponse）。
+func registerNoResponse(cmd wire.Command, fn Handler) {
+	if _, dup := handlers[cmd]; dup {
+		panic(fmt.Sprintf("command: %s 重复注册", cmd))
+	}
+	handlers[cmd] = handlerSpec{fn: fn, noResponse: true}
+}
+
 // Registered 报告某个命令是否已经实现，用于日志与测试。
 func Registered(cmd wire.Command) bool {
 	_, ok := handlers[cmd]
 	return ok
 }
 
+// NoResponse 报告某个命令是否永不产生响应（MS-SMB2 §3.3.5.16 的 CANCEL）。
+//
+// internal/server 用它决定是否要为这条消息记 credit 账。
+func NoResponse(cmd wire.Command) bool {
+	return handlers[cmd].noResponse
+}
+
 // defaultHandler 处理所有未实现的命令（AGENTS.md §5 P2）。
 func defaultHandler(ctx *Context) error {
 	ctx.Log.Debug("未实现的 SMB2 命令", "command", ctx.Header.Command.String(),
@@ -62,6 +83,19 @@ func defaultHandler(ctx *Context) error {
 // 无论成功失败都会产生一条格式正确的响应 —— SMB2 不允许对请求静默不答，
 // 客户端会一直等到超时。
 func Dispatch(ctx *Context) {
+	// 不产生响应的命令（SMB2 CANCEL）在这里短路：它连一条 ERROR Response
+	// 都不能回 —— 那条响应的 MessageId 与被取消的请求相同，客户端会把它
+	// 错配成被取消请求的应答（MS-SMB2 §3.3.5.16）。
+	//
+	// 也正因为如此，这里**刻意跳过**会话定位与验签：验签失败同样不能回
+	// 错误响应，只能丢弃。handler 自己不信任任何前置状态。
+	if spec, ok := handlers[ctx.Header.Command]; ok && spec.noResponse {
+		_ = spec.fn(ctx)
+		ctx.suppress = true
+		ctx.discard()
+		return
+	}
+
 	err := dispatch(ctx)
 	if err != nil {
 		ctx.fail(status.FromVFSError(err))
diff --git a/internal/smb/command/query_info.go b/internal/smb/command/query_info.go
index db560e0..388b67c 100644
--- a/internal/smb/command/query_info.go
+++ b/internal/smb/command/query_info.go
@@ -14,9 +14,17 @@ func init() {
 //
 // 只宣告我们真正做得到的。谎报能力（例如宣告支持 ACL / 压缩 / 加密）
 // 会让客户端发我们处理不了的请求；漏报则会让它保守降级。
-const fsAttributes = wire.FileCasePreservedNames |
+//
+// FILE_NAMED_STREAMS 与 FILE_SUPPORTS_SPARSE_FILES 是 Time Machine 的前置条件：
+// macOS 只有看到这两位才会去查 FileStreamInformation（AFP_Resource/AFP_AfpInfo）
+// 与发 FSCTL_SET_SPARSE / FSCTL_QUERY_ALLOCATED_RANGES（.sparsebundle 的 band 回收）。
+//
+// FILE_CASE_SENSITIVE_SEARCH 按卷的真实能力在 queryFsInfo 里动态清除。
+const fsAttributes = wire.FileCaseSensitiveSearch |
+	wire.FileCasePreservedNames |
 	wire.FileUnicodeOnDisk |
-	wire.FileSupportsSparseFiles
+	wire.FileSupportsSparseFiles |
+	wire.FileNamedStreams
 
 // fsName 是回给客户端的文件系统名。
 //
diff --git a/internal/smb/wire/query_info.go b/internal/smb/wire/query_info.go
index ce8c543..16ce37f 100644
--- a/internal/smb/wire/query_info.go
+++ b/internal/smb/wire/query_info.go
@@ -665,9 +665,38 @@ func (i FsSectorSizeInfo) Encode() []byte {
 	return b
 }
 
-// FsObjectIDInfoSize 是 FileFsObjectIdInformation（MS-FSCC §2.5.6）的字节数。
+// FsObjectIDInfoSize 是 FileFsObjectIdInformation（MS-FSCC §2.5.6）的字节数：
+// ObjectId(16) + ExtendedInfo(48)。
 const FsObjectIDInfoSize = 64
 
+// FsObjectIDInfo 是 FileFsObjectIdInformation（MS-FSCC §2.5.6），固定 64 字节。
+//
+// ExtendedInfo 是 48 字节不透明数据，规范明确说明「客户端不得解释其内容」，
+// 全零是合法取值（Samba 在这里塞自己的版本号，我们不跟）。
+type FsObjectIDInfo struct {
+	ObjectID     [16]byte
+	ExtendedInfo [48]byte
+}
+
+// Encode 编码为 64 字节。
+func (i FsObjectIDInfo) Encode() []byte {
+	b := make([]byte, FsObjectIDInfoSize)
+	copy(b[0:], i.ObjectID[:])
+	copy(b[16:], i.ExtendedInfo[:])
+	return b
+}
+
+// ParseFsObjectIDInfo 解析 FileFsObjectIdInformation（供测试与 Go 客户端使用）。
+func ParseFsObjectIDInfo(data []byte) (FsObjectIDInfo, error) {
+	var i FsObjectIDInfo
+	if err := need(data, FsObjectIDInfoSize); err != nil {
+		return i, fmt.Errorf("FileFsObjectIdInformation: %w", err)
+	}
+	copy(i.ObjectID[:], data[0:16])
+	copy(i.ExtendedInfo[:], data[16:64])
+	return i, nil
+}
+
 func boolByte(v bool) byte {
 	if v {
 		return 1

